import type { CatalogItem } from './CatalogItem'
import type { VariableSet } from './VariableSet'

import type { CatalogItemRecordProducer } from './CatalogItemRecordProducer'
type CatalogClientScriptEvents = 'onLoad' | 'onChange' | 'onSubmit'
import type { VariableReference } from './Variable'

/**
 * Valid UI types for catalog client scripts
 */
type CatalogClientScriptUIType = 'desktop' | 'mobileOrServicePortal' | 'all'

/**
 * Type representing the properties of a Catalog Client Script.
 */
type CatalogClientScriptTarget = {
    /** The catalog item the script applies to. Mutually exclusive with variableSet. */
    catalogItem?: string | CatalogItem | CatalogItemRecordProducer
    /** The applies to the script. */
    appliesTo?: 'item' | 'set'
    /** The variable set the script applies to. Mutually exclusive with catalogItem. */
    variableSet?: string | VariableSet
}

export type CatalogClientScriptProps<E extends CatalogClientScriptEvents> = Now.Internal.WithID<
    {
        /** The name of the client script. */
        name: string
        /** The script to run. */
        script: string
        /** The type of the client script. */
        type?: E
        /**
         * The catalog variable that triggers the script.
         * This property applies only when the type property is set to `onChange`.
         */
        variableName?: string | VariableReference
        /** The ui type of the client script. */
        uiType?: CatalogClientScriptUIType
        /** Whether the script is active. */
        active?: boolean
        /** Whether the script is global. */
        global?: boolean
        /** Whether the script is applies on catalog item view. */
        appliesOnCatalogItemView?: boolean
        /** Whether the script is applies on requested items. */
        appliesOnRequestedItems?: boolean
        /** Whether the script is applies on catalog tasks. */
        appliesOnCatalogTasks?: boolean
        /** Whether the script is applies on target record. */
        appliesOnTargetRecord?: boolean
        /** Whether the script is VA supported. */
        vaSupported?: boolean
        /** The published ref of the client script. */
        publishedRef?: string
        /** Whether the script is isolated. */
        isolateScript?: boolean
    } & CatalogClientScriptTarget
>

/**
 * Creates a Catalog Client Script (`catalog_script_client`).
 *
 * @see https://www.servicenow.com/docs/bundle/zurich-api-reference/page/script/client-scripts/concept/c_CatalogClientScriptCreation.html#title_r_CatalogClientScriptConsid
 */
export function CatalogClientScript<E extends CatalogClientScriptEvents>(config: CatalogClientScriptProps<E>) {
    return config
}
